-- Carga completa de componentes para Neon PostgreSQL
-- Gerado a partir de database/componentes.sqlite
BEGIN;

CREATE EXTENSION IF NOT EXISTS pg_trgm;

ALTER TABLE public.componentes ADD COLUMN IF NOT EXISTS status TEXT NOT NULL DEFAULT 'indisponivel';
ALTER TABLE public.componentes ADD COLUMN IF NOT EXISTS status_cadastro TEXT;
ALTER TABLE public.componentes ADD COLUMN IF NOT EXISTS estoque_atualizado_em TIMESTAMPTZ;

UPDATE public.componentes SET status = 'indisponivel' WHERE status IS NULL OR status = '';

CREATE INDEX IF NOT EXISTS idx_componentes_status ON public.componentes (status);
CREATE INDEX IF NOT EXISTS idx_componentes_status_cadastro ON public.componentes (status_cadastro);

